import Foundation

/// Loads `Resources/Study/fathers-profiles.json` (generated by
/// `scripts/build-study-resources.py` from the hand-curated, sourced
/// `work-content/fathers-profiles.source.json`) and looks profiles up by exact author name — the
/// same string `StudySource.author` carries, since both come from the same database's
/// `father_name` column. A missing profile is not a defect: 0.8's admission rule broadened the
/// default Fathers bank to every patristic-era author the source database carries (~209 names),
/// while sourced profiles were written for the ~60 highest-significance and every council-
/// condemned author — see workstream I's final report for exact coverage and why the remainder
/// isn't guessed at. Callers (`FatherBentLabel`, `FatherProfileSheet`) must treat `nil` as "no
/// sourced profile yet," never synthesize one.
@MainActor
final class FatherProfileStore {
    /// Convenience shared instance for view code (`FatherBentLabel`/`FatherProfileSheet`
    /// default to this so K's card integration is a one-line drop-in); tests inject their own
    /// instance via `init(url:)` instead of touching this singleton.
    static let shared = FatherProfileStore()

    private let profiles: [String: FatherProfile]
    private(set) var diagnostics: [String] = []

    init(url: URL? = AppResources.url("Study/fathers-profiles.json")) {
        guard let url, let data = try? Data(contentsOf: url) else {
            profiles = [:]
            diagnostics.append("fathers-profiles.json missing")
            return
        }
        guard let file = try? JSONDecoder().decode(FatherProfileFile.self, from: data), file.schema == 1 else {
            profiles = [:]
            diagnostics.append("fathers-profiles.json failed to decode or has an unsupported schema")
            return
        }
        profiles = Dictionary(uniqueKeysWithValues: file.profiles.map { ($0.name, $0) })
    }

    /// `nil` when this author has no sourced profile yet (see type doc comment) — not an error.
    func profile(forAuthor name: String) -> FatherProfile? { profiles[name] }

    var count: Int { profiles.count }
    var allProfiles: [FatherProfile] { profiles.values.sorted { $0.name < $1.name } }
}
